cd /home/user/rork-app

echo "=== CHECK FOR RORK PUBLIC ENV VARS IN PRODUCTION ENVIRONMENT ==="
# These are listed in the conversation summary as public envs configured for the project
# They are not required by IVX runtime, but we should verify they are not used
cat > /tmp/check-rork-envs.mjs << 'EOF'
const fs = require('fs');
const path = require('path');

const repoRoot = '/home/user/rork-app';
const publicRorkEnvs = [
  'EXPO_PUBLIC_PROJECT_ID',
  'EXPO_PUBLIC_RORK_API_BASE_URL',
  'EXPO_PUBLIC_RORK_APP_KEY',
  'EXPO_PUBLIC_RORK_AUTH_URL',
  'EXPO_PUBLIC_RORK_FUNCTIONS_URL',
  'EXPO_PUBLIC_RORK_TOOLKIT_SECRET_KEY',
  'EXPO_PUBLIC_TEAM_ID',
  'EXPO_PUBLIC_TOOLKIT_URL',
  'RORK_PUBLIC_GITHUB_TOKEN',
  'RORK_PUBLIC_IVX_AI_KEY',
  'RORK_PUBLIC_IVX_OWNER_EMAIL',
];

const results = {};
for (const env of publicRorkEnvs) {
  const usedInBackend = grepCount(repoRoot, env, ['backend']);
  const usedInExpo = grepCount(repoRoot, env, ['expo']);
  results[env] = { backend: usedInBackend, expo: usedInExpo };
}

function grepCount(root, term, dirs) {
  let count = 0;
  for (const dir of dirs) {
    const full = path.join(root, dir);
    if (!fs.existsSync(full)) continue;
    const files = walk(full);
    for (const f of files) {
      if (f.includes('node_modules') || f.includes('.git')) continue;
      try {
        const content = fs.readFileSync(f, 'utf8');
        if (content.includes(term)) count++;
      } catch {}
    }
  }
  return count;
}

function walk(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else out.push(full);
  }
  return out;
}

console.log(JSON.stringify(results, null, 2));
EOF

node /tmp/check-rork-envs.mjs 2>&1 | head -60

