cd /home/user/rork-app

echo "=== START BACKGROUND DEPLOYMENT WATCH ==="
cat > /tmp/watch-deploy.mjs << 'EOF'
import { appendFileSync } from 'node:fs';
const expectedSha = 'eb4050d7ce093bffe96df4d917f623062754ebe7';
const start = Date.now();
const log = (msg) => {
  const line = `${new Date().toISOString()} ${msg}`;
  console.log(line);
  try { appendFileSync('/tmp/deploy-watch.log', line + '\n'); } catch {}
};
log(`DEPLOY WATCH: expectedSha=${expectedSha}`);
for (let i = 1; i <= 120; i++) {
  try {
    const res = await fetch('https://api.ivxholding.com/health');
    const body = await res.text();
    const sha = body.match(/"commit":"([^"]+)"/)?.[1] ?? 'unknown';
    const elapsed = ((Date.now() - start) / 60000).toFixed(1);
    if (sha === expectedSha) {
      log(`MATCH at ${elapsed}min (iter ${i}): sha=${sha}`);
      process.exit(0);
    } else {
      if (i % 6 === 0) log(`${elapsed}min iter ${i}: sha=${sha} (waiting)`);
    }
  } catch (err) {
    log(`iter ${i}: ERROR ${err.message}`);
  }
  await new Promise((r) => setTimeout(r, 10000));
}
log('TIMEOUT after 20 minutes');
process.exit(1);
EOF

rm -f /tmp/deploy-watch.log
nohup bun /tmp/watch-deploy.mjs > /tmp/deploy-watch.log 2>&1 &
echo $! > /tmp/deploy-watch-pid.txt
echo "Deploy watch PID=$(cat /tmp/deploy-watch-pid.txt)"

